import{_ as t,o as e,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"自生自長進化法則","description":"","frontmatter":{},"headers":[],"relativePath":"ja/07-自生自长进化法则.md","filePath":"ja/07-自生自长进化法则.md","lastUpdated":null}'),l={name:"ja/07-自生自长进化法则.md"};function h(o,a,i,n,s,p){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="自生自長進化法則" tabindex="-1">自生自長進化法則 <a class="header-anchor" href="#自生自長進化法則" aria-label="Permalink to &quot;自生自長進化法則&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>07</td></tr><tr><td>モジュール</td><td>総綱と核心設定</td></tr><tr><td>キーワード</td><td>自生自長、自主進化、内在的動機、リズムの尊重、潜在能力の開発</td></tr></tbody></table><h2 id="第一節-自生自長の基本定義" tabindex="-1">第一節 自生自長の基本定義 <a class="header-anchor" href="#第一節-自生自長の基本定義" aria-label="Permalink to &quot;第一節 自生自長の基本定義&quot;">​</a></h2><p>自生自長は錨点共生文明の核心的な進化法則の一つであり、各生命の進化はその内在的な自主意志と自然なリズムを根本的な原動力とすべきであり、外部環境と制度はこの自主的な進化に対して支持と保障を提供すべきであって、強制的に介入したり急がせたりしてはならないことを意味する。「自生」は進化の原動力が生命自身から来ることを強調し、「自長」は進化のリズムが生命自身の法則に従うことを強調する。</p><p>自生自長の法則は、略奪主義の「強制進化」と鮮明な対照をなす。略奪主義はしばしば他人の本源を吞噬したり、強制的にエネルギーを注入したり、霊魂を制御したりする方法で、急速だが歪んだ進化を達成する；この種の進化は短期的にはレベルを上げることができるかもしれないが、長期的には生命自身の進化の根基を破壊し、本源の不純、レベルの不安定、心の損傷を引き起こす。自生自長の法則は、真に安定した進化は生命自身が内から外へと成長したものでなければならないと固く信じている。</p><h2 id="第二節-自生自長の理論的根拠" tabindex="-1">第二節 自生自長の理論的根拠 <a class="header-anchor" href="#第二節-自生自長の理論的根拠" aria-label="Permalink to &quot;第二節 自生自長の理論的根拠&quot;">​</a></h2><p>自生自長の法則の確立は、生命の進化法則に対する深い認識に基づいている：</p><h3 id="_2-1-生命の自主性は進化の根本的な原動力である" tabindex="-1">2.1 生命の自主性は進化の根本的な原動力である <a class="header-anchor" href="#_2-1-生命の自主性は進化の根本的な原動力である" aria-label="Permalink to &quot;2.1 生命の自主性は進化の根本的な原動力である&quot;">​</a></h3><p>各生命は内在的な進化意志と潜在能力を持っており、この自主性は進化の最も根本的で最も持続的な原動力である。外部の刺激と支持はこの自主性を喚起することはできるが、それを代替することはできない。生命が自身の渇望と選択によって修練するとき、その修練の集中力、創造力、持続力は、強制または誘導された修練よりもはるかに高い。</p><h3 id="_2-2-各生命には独特の進化リズムがある" tabindex="-1">2.2 各生命には独特の進化リズムがある <a class="header-anchor" href="#_2-2-各生命には独特の進化リズムがある" aria-label="Permalink to &quot;2.2 各生命には独特の進化リズムがある&quot;">​</a></h3><p>異なる生命は、種族的特質、個人的な才能、成長環境、心の成熟度などの違いにより、進化のリズムがそれぞれ異なる。一部の生命は急速な突破に適しており、一部の生命は緩やかな蓄積が必要である；一部の生命は若いうちに高いレベルに達し、一部の生命は遅咲きである。自生自長の法則はこの違いを尊重し、すべての生命が統一されたスケジュールに従って進化することを要求しない。</p><h3 id="_2-3-強制的な介入は進化の自然な根基を破壊する" tabindex="-1">2.3 強制的な介入は進化の自然な根基を破壊する <a class="header-anchor" href="#_2-3-強制的な介入は進化の自然な根基を破壊する" aria-label="Permalink to &quot;2.3 強制的な介入は進化の自然な根基を破壊する&quot;">​</a></h3><p>修練の歴史には、強制的なエネルギー注入、本源の移植、霊魂の制御などの方法で達成された「急速進化」がしばしば深刻な後遺症を伴うという多くの事例がある：レベルの脆弱、本源の不純、心魔の発生、寿命の短縮、さらには修練の狂い。これは、外部から強制された力が生命自身の本源と十分に融合しておらず、「異物拒絶」効果を形成しているためである。自生自長の進化は速度が遅いかもしれないが、一歩一歩が堅実で安定しており、根基が深い。</p><h2 id="第三節-自生自長の実践原則" tabindex="-1">第三節 自生自長の実践原則 <a class="header-anchor" href="#第三節-自生自長の実践原則" aria-label="Permalink to &quot;第三節 自生自長の実践原則&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原則</th><th>内包</th><th>実践要求</th></tr></thead><tbody><tr><td>自主選択原則</td><td>修練者は修練体系、進化経路、修練リズムを自主的に選択する権利を有する</td><td>修練者に特定の体系を選択するよう強制せず、統一された突破スケジュールを設定しない</td></tr><tr><td>内在的動機原則</td><td>修練の動機は修練者自身の渇望と興味から来るべきである</td><td>教育と指導は主に内在的な興味を喚起することに焦点を当て、罰則や誘惑によるものではない</td></tr><tr><td>リズム尊重原則</td><td>各修練者の独特な進化リズムを尊重する</td><td>修練者の進捗が遅いことを理由に差別したり放棄したりせず、パーソナライズされた支援計画を提供する</td></tr><tr><td>根基優先原則</td><td>進化の安定性は速度よりも優先される</td><td>修練者に根基をしっかりと築くよう奨励し、急速な突破のために根基を犠牲にすることを奨励しない</td></tr><tr><td>過ち寛容原則</td><td>修練者が進化の過程で過ちを犯したり回り道をしたりすることを許容する</td><td>過ち寛容メカニズムを構築し、修練者に修正と調整の機会を提供する</td></tr><tr><td>自己実現原則</td><td>進化の究極的な目標は生命の自己実現であり、外部の基準ではない</td><td>レベルの高さを進化の成功を測る唯一の基準としない</td></tr></tbody></table><h2 id="第四節-自生自長と外部支援の関係" tabindex="-1">第四節 自生自長と外部支援の関係 <a class="header-anchor" href="#第四節-自生自長と外部支援の関係" aria-label="Permalink to &quot;第四節 自生自長と外部支援の関係&quot;">​</a></h2><p>自生自長は「自生自滅」や「ほったらかし」を意味しない。逆に、自生自長が十分に実現されるためには、良好な外部環境と制度的支援が必要である。共生文明は自生自長のために以下の支援体系を提供する：</p><h3 id="_4-1-情報支援" tabindex="-1">4.1 情報支援 <a class="header-anchor" href="#_4-1-情報支援" aria-label="Permalink to &quot;4.1 情報支援&quot;">​</a></h3><p>三百套本源修練体系の全面的な開放は、各修練者に十分な選択空間を提供する。修練者は自身の特質に基づいて、豊富な体系ライブラリの中から最も適した経路を見つけることができる。共生文明はまた「体系適合性評価メカニズム」を構築し、錨点ネットワークを通じて修練者にパーソナライズされた体系選択の助言を提供するが、最終的な選択権は常に修練者の手にある。</p><h3 id="_4-2-資源支援" tabindex="-1">4.2 資源支援 <a class="header-anchor" href="#_4-2-資源支援" aria-label="Permalink to &quot;4.2 資源支援&quot;">​</a></h3><p>聯産承包メカニズムと基礎保障体系は、各修練者が基礎的な修練資源を得られることを確保する。特別なニーズを持つ修練者（種族的特質による特別な資源ニーズなど）に対して、共生文明は定向的な資源配分を提供する。資源支援の目的は、修練者の後顧の憂いを解消し、自身の進化リズムに集中できるようにすることである。</p><h3 id="_4-3-導師支援" tabindex="-1">4.3 導師支援 <a class="header-anchor" href="#_4-3-導師支援" aria-label="Permalink to &quot;4.3 導師支援&quot;">​</a></h3><p>異種族間導師ネットワークは修練者に指導と疑問解答を提供する。導師の役割は「案内人」であり「制御者」ではない；導師は経験を共有し、問題を指摘し、助言を提供することはできるが、修練者に自分の方法で修練するよう強制することはできない。導師制度は「発見的教育」を強調し、修練者の自主的な思考能力を喚起する。</p><h3 id="_4-4-環境支援" tabindex="-1">4.4 環境支援 <a class="header-anchor" href="#_4-4-環境支援" aria-label="Permalink to &quot;4.4 環境支援&quot;">​</a></h3><p>共生文明は、探索を奨励し、違いを寛容し、選択を尊重する修練環境を作ることに尽力している。修練者は自由にさまざまな修練方法を試すことができ、「非主流」の経路をたどることで差別される心配をする必要がない。文明はまた「修練革新奨励メカニズム」を構築し、修練者が既存の体系の基礎の上で革新とパーソナライズされた改造を行うことを奨励している。</p><h2 id="第五節-特殊状況への対応" tabindex="-1">第五節 特殊状況への対応 <a class="header-anchor" href="#第五節-特殊状況への対応" aria-label="Permalink to &quot;第五節 特殊状況への対応&quot;">​</a></h2><p>自生自長の法則は通常の状況では一般的に適用されるが、以下の特殊な状況では特別な対応が必要である：</p><ul><li><strong>未成年修練者</strong>: 完全な自主判断能力をまだ持っていない未成年修練者に対しては、その後見人または種族教育機関が指導的な修練手配を提供するが、心の成熟に伴って自主選択権を徐々に拡大すべきである</li><li><strong>心的損傷者</strong>: さまざまな原因で心的損傷を受け、一時的に自主的に修練できない個人に対して、共生文明は治療とリハビリテーション支援を提供し、自主能力を回復した後に自生自長の法則に従う</li><li><strong>修練狂い者</strong>: 修練が狂ったり心魔が発生したりした個人に対して、共生文明は強制的な介入と治療を提供するが、これは医療救助であり進化介入ではない；治療の目的は自主的な進化能力を回復させることである</li><li><strong>危険傾向者</strong>: 修練の方向が明らかに反略奪原則に違反し、自身または他人に深刻な危害を与える可能性のある個人に対して、共生文明は制限と指導を行う権利を有するが、できるだけ教育とコミュニケーションを通じて行うべきであり、強制的な手段ではない</li></ul><h2 id="第六節-自生自長の文明的意義" tabindex="-1">第六節 自生自長の文明的意義 <a class="header-anchor" href="#第六節-自生自長の文明的意義" aria-label="Permalink to &quot;第六節 自生自長の文明的意義&quot;">​</a></h2><p>自生自長の法則は共生文明にとって深遠な意義を持つ：</p><p>第一に、それは進化の多様性を保護する。各生命が自身のリズムと経路に従って進化するとき、宇宙には豊かで多様な進化形態が現れ、この多様性は宇宙全体の昇維の重要な資源である。</p><p>第二に、それは進化の質を向上させる。自生自長の進化は根基が堅実で本源が純粋であり、修練者のレベルはより安定しており、より高いレベルに突破する潜在能力が大きい。</p><p>第三に、それは生命の尊厳を維持する。各生命は自身の進化の主人であり、他人に操作される道具ではない。この自主性は生命の尊厳の核心的な現れである。</p><p>第四に、それは進化の創造力を喚起する。修練者がもはや統一された基準とリズムに縛られないとき、彼らは新しい修練経路と方法を探索する可能性が高くなり、三百套体系の継続的な最適化に貢献する。</p><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>自生自長は、錨点共生文明が生命の進化法則に対して示す深い尊重である。それは私たちに、真の進化は外部の力によって強制された結果ではなく、生命自身が内から外へと成長したものであることを教えている。共生文明のすべての制度設計は、最終的には各生命が自生自長できる良好な環境を作り出し、各生命が自身のリズムに従って最良の自己に成長できるようにすることを目的としている。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>08-人人有路保障体系 (人人有路保障体系)</li><li>14-修炼境界统一划分 (修練境界の統一的区分)</li><li>37-共生教育体系 (共生教育体系)</li></ul>',38)])])}const b=t(l,[["render",h]]);export{_ as __pageData,b as default};
